Tool response:
Tool: add_series_a_shares
Description: Record additional Series A shares acquired for a fund's portfolio holding.
Updates total shares and cost basis while preserving prior capital activities.
Parameters:
    {
      "type": "object",
      "properties": {
        "fund_id": {
          "type": "integer",
          "title": "Fund Id",
          "description": ""
        },
        "company_id": {
          "type": "integer",
          "title": "Company Id",
          "description": ""
        },
        "stakeholder_id": {
          "type": "integer",
          "description": "Internal ID of the stakeholder record associated with the fund",
          "title": "Stakeholder Id"
        },
        "shares": {
          "type": "integer",
          "exclusiveMinimum": 0.0,
          "title": "Shares"
        },
        "price_per_share": {
          "type": "number",
          "minimum": 0.0,
          "title": "Price Per Share"
        },
        "activity_date": {
          "type": "string",
          "title": "Activity Date"
        }
      },
      "required": [
        "fund_id",
        "company_id",
        "stakeholder_id",
        "shares",
        "price_per_share",
        "activity_date"
      ]
    }
